var p = (t - start) / (land - start);
if (p < 0) p = 0; if (p > 1) p = 1;
var sx = 190, sy = 178;
var ex = 125, ey = 292;
var x = sx + (ex - sx) * p;
var y = sy + (ey - sy) * p * p;
ctx.save();
ctx.fillStyle = 'rgba(245,250,255,0.98)';
ctx.strokeStyle = '#2B5F8F';
ctx.lineWidth = 1.4;
ctx.beginPath();
ctx.ellipse(x, y, 5.2, 7.6, 0, 0, Math.PI * 2);
ctx.fill();
ctx.stroke();
if (p >= 1) {
  ctx.fillStyle = 'rgba(235,248,255,0.98)';
